    { text: "Ad quality matters just as much as budget.", text2: "Google uses factors like click-through rate (CTR), ad relevance, and landing page experience to determine ad placement, meaning the highest bidder does not always win." },
    { text: "Google Ads can help businesses identify high-converting keywords.", text2: "Paid campaigns provide valuable keyword and conversion data that marketers can use to improve broader SEO and content marketing strategies." },
    { text: "Successful Google Ads campaigns require testing and ongoing optimization.", text2: "Advertisers need to regularly monitor metrics like impressions, clicks, conversions, and cost-per-click (CPC) while testing ad copy, keywords, and landing pages to improve performance over time." },
    { text: "Small businesses can compete against larger brands using Google Ads.", text2: "Even companies without strong organic rankings can gain visibility and attract customers by targeting the right keywords and building relevant ad campaigns." }
